{
  "success": true,
  "severity": "success",
  "message": "Inventory moved successfully",
  "data": {
    "Moved Inventory": $state.context.INFO.inventory.{
      "ID": id,
      "Serial Number": serialNumber,
      "Previous Storage Unit": storageUnit.code,
      "Removed From Handling Unit ID": $state.context.INPUT.removeFromHandlingUnit ? $coalesce([handlingUnitId, "N/A"])
    },
    "New Storage Unit": $state.context.INPUT.storageUnit.code
  }
}

{
  "success": false,
  "severity": "error",
  "title": "Inventory Status Mismatch",
  "message": "The inventory status does not match the storage unit's default inventory status. Update the inventory status or choose a different storage unit to fix this issue.",
  "data": {
    "Storage Unit": $state.context.INFO.storageUnit.code,
    "Storage Unit ID": $state.context.INPUT.storageUnitId,
    "Default Inventory Status": $state.context.INFO.storageUnit.defaultInventoryStatus.code,
    "Inventory Serial Number": $state.context.INFO.inventory.serialNumber,
    "Inventory Status Code": $state.context.INFO.inventory.inventoryStatusId
  }
}

